using ProjectTasks.BUS;using System.Data;
namespace ProjectTasks.GUI;
public sealed class MainForm:Form
{
 readonly TaskService svc=new();readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView projectGrid=Grid(),taskGrid=Grid(),lateGrid=Grid(),completionGrid=Grid();readonly TextBox projectName=new(){Width=250},taskName=new(){Width=240},description=new(){Width=300,Height=54,Multiline=true},search=new(){Width=180};readonly ComboBox projectStatus=new(){Width=150,DropDownStyle=ComboBoxStyle.DropDownList},taskProject=new(){Width=200,DropDownStyle=ComboBoxStyle.DropDownList},taskFilter=new(){Width=130,DropDownStyle=ComboBoxStyle.DropDownList},priority=new(){Width=100,DropDownStyle=ComboBoxStyle.DropDownList},status=new(){Width=130,DropDownStyle=ComboBoxStyle.DropDownList};readonly DateTimePicker start=new(){Format=DateTimePickerFormat.Short,ShowCheckBox=true,Width=130},end=new(){Format=DateTimePickerFormat.Short,ShowCheckBox=true,Width=130},due=new(){Format=DateTimePickerFormat.Short,ShowCheckBox=true,Width=130};readonly CheckedListBox assignees=new(){Width=245,Height=74,CheckOnClick=true};DataTable? projectTable,memberTable;int? selectedProject,selectedTask;
 public MainForm(){Text="TaskFlow | Quản lý dự án & công việc";Width=1300;Height=820;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(246,248,250);BuildHome();BuildProjects();BuildTasks();BuildReports();Controls.Add(tabs);Shown+=(_,_)=>RefreshAll();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};TabPage Page(string s){var p=new TabPage(s){Padding=new Padding(12),BackColor=Color.FromArgb(246,248,250)};tabs.TabPages.Add(p);return p;}static Label L(string s)=>new(){Text=s,AutoSize=true,Margin=new Padding(6,9,2,2)};static Button B(string s,EventHandler e){var b=new Button{Text=s,AutoSize=true,Height=33,Margin=new Padding(3),BackColor=Color.White};b.Click+=e;return b;}static FlowLayoutPanel Bar(int h=90)=>new(){Dock=DockStyle.Top,Height=h,Padding=new Padding(0,5,0,5),WrapContents=true};
 void BuildHome(){var p=Page("Tổng quan");p.Controls.Add(new Label{Text="TASKFLOW  |  QUẢN LÝ DỰ ÁN & TIẾN ĐỘ",Font=new Font("Segoe UI",23,FontStyle.Bold),ForeColor=Color.FromArgb(30,64,114),AutoSize=true,Location=new Point(28,28)});p.Controls.Add(new Label{Text="Phân công nhóm • Theo dõi Kanban • Cảnh báo hạn • Báo cáo hoàn thành",Font=new Font("Segoe UI",13),AutoSize=true,Location=new Point(32,82)});var box=new Panel{Location=new Point(32,140),Size=new Size(570,190),BackColor=Color.White};box.Controls.Add(new Label{Text="Kết nối SQL Server",Font=new Font("Segoe UI",16,FontStyle.Bold),Location=new Point(20,18),AutoSize=true});box.Controls.Add(new Label{Text=@"Server: localhost\SQLEXPRESS  |  Database: ProjectTaskDB",Location=new Point(20,58),AutoSize=true});box.Controls.Add(new Label{Text="Mô hình 3 tầng DTO → DAL → BUS → GUI",Location=new Point(20,95),AutoSize=true});var stats=new Label{Location=new Point(20,130),AutoSize=true,Name="stats"};box.Controls.Add(stats);p.Controls.Add(box);}
 void BuildProjects(){var p=Page("Dự án");var top=Bar(110);projectStatus.Items.AddRange(new object[]{"Đang chạy","Hoàn thành","Tạm dừng"});projectStatus.SelectedIndex=0;top.Controls.AddRange(new Control[]{L("Tên dự án"),projectName,L("Bắt đầu"),start,L("Kết thúc"),end,L("Trạng thái"),projectStatus,B("Thêm",(_,_)=>SaveProject(null)),B("Cập nhật",(_,_)=>SaveProject(selectedProject)),B("Xóa",(_,_)=>DeleteProject()),B("Làm mới",(_,_)=>LoadProjects())});p.Controls.Add(projectGrid);p.Controls.Add(top);projectGrid.SelectionChanged+=(_,_)=>SelectProject();}
 void BuildTasks(){var p=Page("Công việc / Kanban");var filters=Bar(48);taskProject.SelectedIndexChanged+=(_,_)=>LoadTasks();taskFilter.Items.AddRange(new object[]{"Tất cả","To Do","In Progress","Review","Done"});taskFilter.SelectedIndex=0;taskFilter.SelectedIndexChanged+=(_,_)=>LoadTasks();filters.Controls.AddRange(new Control[]{L("Dự án"),taskProject,L("Trạng thái"),taskFilter,L("Tìm task"),search,B("Tìm",(_,_)=>LoadTasks())});var edit=Bar(178);priority.Items.AddRange(new object[]{"Cao","Trung bình","Thấp"});priority.SelectedIndex=1;status.Items.AddRange(new object[]{"To Do","In Progress","Review","Done"});status.SelectedIndex=0;edit.Controls.AddRange(new Control[]{L("Tên task"),taskName,L("Hạn nộp"),due,L("Ưu tiên"),priority,L("Trạng thái"),status,L("Mô tả"),description,L("Giao cho thành viên (chọn nhiều)"),assignees,B("Tạo task",(_,_)=>SaveTask(null)),B("Lưu task & phân công",(_,_)=>SaveTask(selectedTask)),B("Xóa task",(_,_)=>DeleteTask()),B("Đánh dấu Done",(_,_)=>MarkDone())});p.Controls.Add(taskGrid);p.Controls.Add(edit);p.Controls.Add(filters);taskGrid.SelectionChanged+=(_,_)=>SelectTask();}
 void BuildReports(){var p=Page("Báo cáo");var tabs2=new TabControl{Dock=DockStyle.Fill};var a=new TabPage("Công việc trễ hạn");var b=new TabPage("Tiến độ thành viên");lateGrid.Dock=DockStyle.Fill;completionGrid.Dock=DockStyle.Fill;a.Controls.Add(lateGrid);b.Controls.Add(completionGrid);tabs2.TabPages.Add(a);tabs2.TabPages.Add(b);var top=Bar(45);top.Controls.Add(B("Cập nhật báo cáo",(_,_)=>LoadReports()));p.Controls.Add(tabs2);p.Controls.Add(top);}
 void RefreshAll(){try{projectTable=svc.Repository.Projects();memberTable=svc.Repository.Members();LoadProjects();LoadTaskLookups();LoadTasks();LoadReports();var stats=Controls.Find("stats",true).FirstOrDefault() as Label;if(stats!=null)stats.Text=$"{svc.Repository.Scalar("SELECT COUNT(*) FROM DuAn")} dự án   •   {svc.Repository.Scalar("SELECT COUNT(*) FROM CongViec")} công việc   •   {svc.Repository.Scalar("SELECT COUNT(*) FROM CongViec WHERE TrangThai=N'Done'")} đã hoàn thành";}catch(Exception ex){Error(ex);}}
 void LoadProjects(){projectTable=svc.Repository.Projects();projectGrid.DataSource=projectTable;}
 void LoadTaskLookups(){if(projectTable==null)projectTable=svc.Repository.Projects();taskProject.DataSource=projectTable.Copy();taskProject.DisplayMember="TenDuAn";taskProject.ValueMember="MaDuAn";taskProject.SelectedIndex=projectTable.Rows.Count>0?0:-1;if(memberTable==null)memberTable=svc.Repository.Members();assignees.Items.Clear();foreach(DataRow r in memberTable.Rows)assignees.Items.Add(new MemberChoice(Convert.ToInt32(r["MaThanhVien"]),r["HoTen"].ToString()!));}
 void LoadTasks(){if(taskProject.SelectedValue is null)return;int pid=int.TryParse(taskProject.SelectedValue.ToString(),out var n)?n:0;var t=svc.Repository.Tasks(pid,taskFilter.SelectedItem?.ToString()??"Tất cả");if(!string.IsNullOrWhiteSpace(search.Text)){var v=search.Text.Replace("'","''");var rows=t.Select($"TenTask LIKE '%{v}%' OR NguoiPhuTrach LIKE '%{v}%'");t=rows.Length==0?t.Clone():rows.CopyToDataTable();}taskGrid.DataSource=t;if(taskGrid.Columns.Contains("MaDuAn"))taskGrid.Columns["MaDuAn"]!.Visible=false;if(taskGrid.Columns.Contains("MoTa"))taskGrid.Columns["MoTa"]!.Visible=false;}
 void SelectProject(){if(projectGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;selectedProject=Convert.ToInt32(r["MaDuAn"]);projectName.Text=r["TenDuAn"].ToString();projectStatus.SelectedItem=r["TrangThai"].ToString();start.Checked=r["NgayBatDau"]!=DBNull.Value;if(start.Checked)start.Value=Convert.ToDateTime(r["NgayBatDau"]);end.Checked=r["NgayKetThuc"]!=DBNull.Value;if(end.Checked)end.Value=Convert.ToDateTime(r["NgayKetThuc"]);}
 void SaveProject(int? id){try{svc.ValidateProject(projectName.Text);svc.Repository.SaveProject(id,projectName.Text.Trim(),start.Checked?start.Value.Date:null,end.Checked?end.Value.Date:null,projectStatus.SelectedItem?.ToString()??"Đang chạy");LoadProjects();LoadTaskLookups();LoadTasks();MessageBox.Show("Đã lưu dự án vào ProjectTaskDB.");}catch(Exception ex){Error(ex);}}
 void DeleteProject(){if(selectedProject is null)return;try{svc.Repository.DeleteProject(selectedProject.Value);selectedProject=null;LoadProjects();LoadTaskLookups();LoadTasks();}catch(Exception ex){Error(ex);}}
 void SelectTask(){if(taskGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;selectedTask=Convert.ToInt32(r["MaTask"]);taskName.Text=r["TenTask"].ToString();description.Text=r["MoTa"]==DBNull.Value?"":r["MoTa"].ToString();due.Checked=r["HanNop"]!=DBNull.Value;if(due.Checked)due.Value=Convert.ToDateTime(r["HanNop"]);priority.SelectedItem=r["DoUuTien"].ToString();status.SelectedItem=r["TrangThai"].ToString();var chosen=svc.Repository.AssignedMembers(selectedTask.Value);for(int i=0;i<assignees.Items.Count;i++)assignees.SetItemChecked(i,chosen.Contains(((MemberChoice)assignees.Items[i]!).Id));}
 void SaveTask(int? id){try{int project=int.TryParse(taskProject.SelectedValue?.ToString(),out var x)?x:0;svc.ValidateTask(taskName.Text,project);var assigned=assignees.CheckedItems.Cast<MemberChoice>().Select(m=>m.Id);selectedTask=svc.Repository.SaveTask(id,project,taskName.Text.Trim(),description.Text,due.Checked?due.Value.Date:null,priority.SelectedItem?.ToString()??"Trung bình",status.SelectedItem?.ToString()??"To Do",assigned);LoadTasks();MessageBox.Show("Đã lưu task và danh sách thành viên được giao.");}catch(Exception ex){Error(ex);}}
 void DeleteTask(){if(selectedTask is null)return;try{svc.Repository.DeleteTask(selectedTask.Value);selectedTask=null;LoadTasks();}catch(Exception ex){Error(ex);}}
 void MarkDone(){if(taskGrid.CurrentRow?.DataBoundItem is not DataRowView r){MessageBox.Show("Chọn một task trước.");return;}try{svc.Repository.SetStatus(Convert.ToInt32(r["MaTask"]),"Done");LoadTasks();MessageBox.Show("Đã cập nhật trạng thái Done bằng truy vấn tham số.");}catch(Exception ex){Error(ex);}}
 void LoadReports(){lateGrid.DataSource=svc.Overdue();completionGrid.DataSource=svc.Repository.Completion();}
 void Error(Exception ex)=>MessageBox.Show(ex.Message,"Có lỗi",MessageBoxButtons.OK,MessageBoxIcon.Warning);
 sealed record MemberChoice(int Id,string Name){public override string ToString()=>Name;}
}
